import React, { useState, useEffect, useRef } from 'react';
import {
  Play,
  Pause,
  SkipBack,
  SkipForward,
  Repeat,
  VolumeX,
  X,
  ChevronUp,
  ChevronDown,
  UserCheck,
} from 'lucide-react';
import { Reciter, Surah, Ayah } from '../types/quran';
import { POPULAR_RECITERS, getAyahAudioUrl } from '../utils/audioReciters';
import { formatTime } from '../utils/arabicUtils';

interface AudioPlayerBarProps {
  currentSurah: Surah;
  currentAyahNumber: number;
  selectedReciter: Reciter;
  onSelectReciter: (reciter: Reciter) => void;
  onClose: () => void;
  onAyahChange: (ayahNum: number) => void;
  isOpen: boolean;
}

export const AudioPlayerBar: React.FC<AudioPlayerBarProps> = ({
  currentSurah,
  currentAyahNumber,
  selectedReciter,
  onSelectReciter,
  onClose,
  onAyahChange,
  isOpen,
}) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [repeatMode, setRepeatMode] = useState<1 | 3 | 5 | 99>(1); // 99 = continuous repeat
  const [repeatCounter, setRepeatCounter] = useState(0);
  const [playbackSpeed, setPlaybackSpeed] = useState<number>(1);
  const [showReciterPicker, setShowReciterPicker] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  const currentAyah =
    currentSurah.ayahs.find((a) => a.numberInSurah === currentAyahNumber) || currentSurah.ayahs[0];

  // Update audio source when reciter, surah, or ayah changes
  useEffect(() => {
    const url = getAyahAudioUrl(selectedReciter.id, currentSurah.number, currentAyahNumber);
    if (!audioRef.current) {
      audioRef.current = new Audio(url);
    } else {
      audioRef.current.src = url;
    }

    audioRef.current.playbackRate = playbackSpeed;

    const audio = audioRef.current;

    const handleTimeUpdate = () => setCurrentTime(audio.currentTime);
    const handleLoadedMetadata = () => setDuration(audio.duration);
    const handleEnded = () => {
      // Handle repeat mode
      if (repeatMode === 99 || repeatCounter + 1 < repeatMode) {
        setRepeatCounter((prev) => prev + 1);
        audio.currentTime = 0;
        audio.play().catch(() => {});
      } else {
        setRepeatCounter(0);
        // Advance to next Ayah in Surah if available
        if (currentAyahNumber < currentSurah.ayahs.length) {
          onAyahChange(currentAyahNumber + 1);
        } else {
          setIsPlaying(false);
        }
      }
    };

    audio.addEventListener('timeupdate', handleTimeUpdate);
    audio.addEventListener('loadedmetadata', handleLoadedMetadata);
    audio.addEventListener('ended', handleEnded);

    if (isPlaying) {
      audio.play().catch((e) => {
        console.warn('Autoplay blocked', e);
        setIsPlaying(false);
      });
    }

    return () => {
      audio.removeEventListener('timeupdate', handleTimeUpdate);
      audio.removeEventListener('loadedmetadata', handleLoadedMetadata);
      audio.removeEventListener('ended', handleEnded);
    };
  }, [selectedReciter.id, currentSurah.number, currentAyahNumber, repeatMode, repeatCounter]);

  const togglePlay = () => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.pause();
      setIsPlaying(false);
    } else {
      audioRef.current
        .play()
        .then(() => setIsPlaying(true))
        .catch(() => setIsPlaying(false));
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = Number(e.target.value);
    if (audioRef.current) {
      audioRef.current.currentTime = val;
      setCurrentTime(val);
    }
  };

  const cycleSpeed = () => {
    const speeds = [0.75, 1.0, 1.25];
    const currentIdx = speeds.indexOf(playbackSpeed);
    const nextSpeed = speeds[(currentIdx + 1) % speeds.length];
    setPlaybackSpeed(nextSpeed);
    if (audioRef.current) {
      audioRef.current.playbackRate = nextSpeed;
    }
  };

  const cycleRepeat = () => {
    const modes: (1 | 3 | 5 | 99)[] = [1, 3, 5, 99];
    const currentIdx = modes.indexOf(repeatMode);
    const next = modes[(currentIdx + 1) % modes.length];
    setRepeatMode(next);
    setRepeatCounter(0);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed bottom-0 left-0 right-0 z-50 bg-stone-900/95 backdrop-blur-md text-white border-t border-stone-800 shadow-2xl p-3 sm:p-4 animate-in slide-in-from-bottom">
      <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-3">
        {/* Reciter Info & Surah Info */}
        <div className="flex items-center gap-3 w-full md:w-auto justify-between md:justify-start">
          <div className="flex items-center gap-2.5">
            <div className="w-10 h-10 rounded-xl bg-emerald-800 flex items-center justify-center text-amber-300 font-serif font-bold text-lg shadow-inner">
              قرآن
            </div>
            <div>
              <div className="flex items-center gap-2">
                <span className="font-bold text-sm text-stone-100 font-serif">
                  سورة {currentSurah.name} (آية {currentAyahNumber})
                </span>
                {selectedReciter.hasTeacherStyle && (
                  <span className="text-[10px] bg-emerald-900/90 text-emerald-300 border border-emerald-700 px-1.5 py-0.2 rounded-md font-medium">
                    مصحف معلّم
                  </span>
                )}
              </div>
              <button
                onClick={() => setShowReciterPicker(!showReciterPicker)}
                className="text-xs text-stone-400 hover:text-emerald-400 flex items-center gap-1 transition-colors"
              >
                <span>القارئ: {selectedReciter.name}</span>
                <ChevronDown className="w-3.5 h-3.5" />
              </button>
            </div>
          </div>

          <button onClick={onClose} className="md:hidden text-stone-400 hover:text-white p-1">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Audio Controls */}
        <div className="flex flex-col items-center gap-1.5 w-full md:max-w-md">
          <div className="flex items-center gap-4">
            {/* Speed Toggle */}
            <button
              onClick={cycleSpeed}
              className="text-[11px] font-bold text-stone-400 hover:text-white px-2 py-1 rounded-md hover:bg-stone-800 transition-colors"
              title="سرعة التلاوة"
            >
              {playbackSpeed}x
            </button>

            {/* Prev Ayah */}
            <button
              onClick={() => onAyahChange(Math.max(1, currentAyahNumber - 1))}
              disabled={currentAyahNumber <= 1}
              className="text-stone-300 hover:text-white disabled:opacity-30 transition-colors p-1"
              title="الآية السابقة"
            >
              <SkipForward className="w-4 h-4" />
            </button>

            {/* Play / Pause Main Button */}
            <button
              onClick={togglePlay}
              className="w-10 h-10 rounded-full bg-emerald-600 hover:bg-emerald-500 text-white flex items-center justify-center shadow-lg transition-transform active:scale-95 cursor-pointer"
            >
              {isPlaying ? <Pause className="w-5 h-5" /> : <Play className="w-5 h-5 mr-0.5" />}
            </button>

            {/* Next Ayah */}
            <button
              onClick={() =>
                onAyahChange(Math.min(currentSurah.ayahs.length, currentAyahNumber + 1))
              }
              disabled={currentAyahNumber >= currentSurah.ayahs.length}
              className="text-stone-300 hover:text-white disabled:opacity-30 transition-colors p-1"
              title="الآية التالية"
            >
              <SkipBack className="w-4 h-4" />
            </button>

            {/* Repeat Mode */}
            <button
              onClick={cycleRepeat}
              className={`flex items-center gap-1 text-[11px] font-semibold px-2 py-1 rounded-md transition-colors ${
                repeatMode > 1
                  ? 'bg-emerald-950 text-emerald-300 border border-emerald-800'
                  : 'text-stone-400 hover:text-white'
              }`}
              title="تكرار الآية لتثبيت الحفظ"
            >
              <Repeat className="w-3.5 h-3.5" />
              <span>{repeatMode === 99 ? '∞' : `${repeatMode}x`}</span>
            </button>
          </div>

          {/* Progress Bar & Timestamps */}
          <div className="flex items-center gap-2 w-full text-[10px] text-stone-400">
            <span>{formatTime(currentTime)}</span>
            <input
              type="range"
              min={0}
              max={duration || 100}
              value={currentTime}
              onChange={handleSeek}
              className="w-full h-1 bg-stone-700 rounded-lg appearance-none cursor-pointer accent-emerald-500"
            />
            <span>{formatTime(duration)}</span>
          </div>
        </div>

        {/* Close Button Desktop */}
        <div className="hidden md:flex items-center gap-3">
          <button
            onClick={onClose}
            className="text-stone-400 hover:text-white p-2 rounded-lg hover:bg-stone-800 transition-colors cursor-pointer"
            title="إغلاق المشغل"
          >
            <X className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Reciters Modal / Dropdown Picker */}
      {showReciterPicker && (
        <div className="max-w-2xl mx-auto mt-3 pt-3 border-t border-stone-800 grid grid-cols-1 sm:grid-cols-2 gap-2 text-xs">
          {POPULAR_RECITERS.map((r) => {
            const isCurrent = r.id === selectedReciter.id;
            return (
              <button
                key={r.id}
                onClick={() => {
                  onSelectReciter(r);
                  setShowReciterPicker(false);
                }}
                className={`p-2.5 rounded-xl text-right flex items-center justify-between transition-colors ${
                  isCurrent
                    ? 'bg-emerald-900/80 text-emerald-200 border border-emerald-600'
                    : 'bg-stone-800/80 hover:bg-stone-700 text-stone-300'
                }`}
              >
                <div>
                  <div className="font-bold text-stone-100">{r.name}</div>
                  <div className="text-[11px] text-stone-400">{r.description}</div>
                </div>
                {isCurrent && <UserCheck className="w-4 h-4 text-emerald-400" />}
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import {
  Trophy,
  Flame,
  Sparkles,
  UserPlus,
  CheckCircle2,
  Send,
  Crown,
  Medal,
  Target,
  Play,
  Heart,
  Users,
} from 'lucide-react';
import { FriendUser, QuranChallenge } from '../types/quran';
import { saveFriends, saveChallenges } from '../services/storageService';

interface CompetitionLeaderboardProps {
  friends: FriendUser[];
  challenges: QuranChallenge[];
  onStartChallenge: (challenge: QuranChallenge) => void;
  onRefresh: () => void;
}

export const CompetitionLeaderboard: React.FC<CompetitionLeaderboardProps> = ({
  friends,
  challenges,
  onStartChallenge,
  onRefresh,
}) => {
  const [showAddFriend, setShowAddFriend] = useState(false);
  const [friendNameInput, setFriendNameInput] = useState('');
  const [sentCheers, setSentCheers] = useState<Record<string, string>>({});

  // Sort by points descending
  const sortedFriends = [...friends]
    .sort((a, b) => b.points - a.points)
    .map((f, idx) => ({
      ...f,
      rank: idx + 1,
    }));

  const handleSendCheer = (friendId: string, cheerText: string) => {
    setSentCheers((prev) => ({ ...prev, [friendId]: cheerText }));
    setTimeout(() => {
      setSentCheers((prev) => {
        const next = { ...prev };
        delete next[friendId];
        return next;
      });
    }, 4000);
  };

  const handleAddFriend = (e: React.FormEvent) => {
    e.preventDefault();
    if (!friendNameInput.trim()) return;

    const newFriend: FriendUser = {
      id: `friend_${Date.now()}`,
      name: friendNameInput.trim(),
      avatar: '🌟',
      points: Math.floor(Math.random() * 800) + 1200,
      versesToday: Math.floor(Math.random() * 20) + 10,
      streakDays: Math.floor(Math.random() * 7) + 2,
      accuracy: 95,
      rank: friends.length + 1,
      badge: 'رفيق الحفظ',
      lastActive: 'الآن',
    };

    const updated = [...friends, newFriend];
    saveFriends(updated);
    setShowAddFriend(false);
    setFriendNameInput('');
    onRefresh();
  };

  return (
    <div className="max-w-5xl mx-auto space-y-8">
      {/* Hero Header */}
      <div className="bg-gradient-to-r from-emerald-950 via-emerald-900 to-teal-950 text-white rounded-3xl p-6 sm:p-8 shadow-sm relative overflow-hidden">
        <div className="relative z-10 max-w-2xl space-y-3">
          <div className="inline-flex items-center gap-2 bg-amber-500/20 text-amber-300 border border-amber-500/30 px-3 py-1 rounded-full text-xs font-semibold">
            <Trophy className="w-3.5 h-3.5" />
            <span>وفي ذلك فليتنافس المتنافسون</span>
          </div>
          <h1 className="text-2xl sm:text-3xl font-bold tracking-tight font-serif">
            حلقة التنافس ومسابقة الأصدقاء
          </h1>
          <p className="text-xs sm:text-sm text-emerald-100/90 leading-relaxed">
            الصحبة الصالحة تشحذ الهمم وتعين على الاستمرار في تعاهد القرآن. نافس أصدقاءك في حفظ
            ومراجعة الآيات، واجمع الحسنات، وتصدر لوحة الشرف الأسبوعية.
          </p>
        </div>
      </div>

      {/* Podium Top 3 */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 pt-2">
        {sortedFriends.slice(0, 3).map((user, idx) => {
          const isFirst = idx === 0;
          const isSecond = idx === 1;
          const isThird = idx === 2;

          return (
            <div
              key={user.id}
              className={`bg-white rounded-3xl p-5 border text-center flex flex-col items-center justify-between relative shadow-xs ${
                isFirst
                  ? 'border-amber-400 bg-gradient-to-b from-amber-50/50 to-white ring-2 ring-amber-300 sm:-translate-y-2'
                  : 'border-stone-200'
              }`}
            >
              {isFirst && (
                <div className="absolute -top-3.5 bg-amber-500 text-white p-1 rounded-full shadow-md">
                  <Crown className="w-5 h-5" />
                </div>
              )}

              <div className="space-y-3 w-full">
                <div className="relative inline-block mt-2">
                  <div className="w-16 h-16 rounded-full bg-stone-100 flex items-center justify-center text-3xl shadow-inner border border-stone-200">
                    {user.avatar}
                  </div>
                  <span
                    className={`absolute -bottom-1 -right-1 w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold text-white shadow-xs ${
                      isFirst ? 'bg-amber-500' : isSecond ? 'bg-stone-500' : 'bg-amber-700'
                    }`}
                  >
                    {user.rank}
                  </span>
                </div>

                <div>
                  <h3 className="font-bold text-stone-900 text-sm">{user.name}</h3>
                  <span className="text-[11px] text-emerald-700 font-medium bg-emerald-50 px-2 py-0.5 rounded-md">
                    {user.badge}
                  </span>
                </div>
              </div>

              <div className="w-full mt-4 pt-3 border-t border-stone-100 space-y-1.5 text-xs">
                <div className="flex justify-between text-stone-600">
                  <span>الحسنات والنقاط</span>
                  <span className="font-bold text-stone-900">
                    {user.points.toLocaleString('ar-EG')}
                  </span>
                </div>
                <div className="flex justify-between text-stone-600">
                  <span>آيات اليوم</span>
                  <span className="font-semibold text-emerald-700">{user.versesToday} آية</span>
                </div>
                <div className="flex justify-between text-stone-600">
                  <span>التتابع</span>
                  <span className="font-semibold text-amber-600 flex items-center gap-0.5">
                    <Flame className="w-3.5 h-3.5 fill-amber-500 text-amber-500" />
                    {user.streakDays} أيام
                  </span>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Daily Quran Challenges */}
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Target className="w-5 h-5 text-emerald-700" />
            <h2 className="text-lg font-bold text-stone-900">تحديات التسميع اليومية</h2>
          </div>
          <span className="text-xs text-stone-500">تتجدد يومياً لنيل نقاط وحسنات إضافية</span>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {challenges.map((challenge) => (
            <div
              key={challenge.id}
              className="bg-white rounded-2xl border border-stone-200 p-5 shadow-xs flex flex-col justify-between space-y-3 hover:border-emerald-300 transition-colors"
            >
              <div className="space-y-2">
                <div className="flex items-center justify-between text-xs">
                  <span className="bg-amber-50 text-amber-900 border border-amber-200 px-2 py-0.5 rounded-md font-semibold">
                    +{challenge.rewardPoints} نقطة
                  </span>
                  <span className="text-stone-500">{challenge.difficulty}</span>
                </div>
                <h3 className="font-bold text-stone-900 text-sm leading-snug">{challenge.title}</h3>
              </div>

              <div className="pt-2 flex items-center justify-between border-t border-stone-100 text-xs">
                <span className="text-stone-500">ينتهي خلال {challenge.expiresInHours} ساعة</span>
                <button
                  onClick={() => onStartChallenge(challenge)}
                  className="flex items-center gap-1 bg-emerald-700 hover:bg-emerald-800 text-white font-semibold px-3 py-1.5 rounded-lg transition-colors cursor-pointer"
                >
                  <Play className="w-3.5 h-3.5" />
                  <span>بدء التحدي</span>
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Friends Ranking Table & Interactive Encouragements */}
      <div className="bg-white rounded-3xl border border-stone-200 shadow-xs overflow-hidden">
        <div className="p-5 border-b border-stone-100 flex flex-wrap items-center justify-between gap-3">
          <div className="flex items-center gap-2">
            <Users className="w-5 h-5 text-emerald-700" />
            <h2 className="text-base font-bold text-stone-900">ترتيب حلقة الحفظ والأصدقاء</h2>
          </div>

          <button
            onClick={() => setShowAddFriend(true)}
            className="flex items-center gap-1.5 bg-emerald-50 hover:bg-emerald-100 text-emerald-800 border border-emerald-200 text-xs font-semibold px-3.5 py-2 rounded-xl transition-colors cursor-pointer"
          >
            <UserPlus className="w-4 h-4" />
            <span>إضافة صديق للحلقة</span>
          </button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-right text-xs">
            <thead className="bg-stone-50 text-stone-600 font-semibold border-b border-stone-100">
              <tr>
                <th className="py-3 px-4">الترتيب</th>
                <th className="py-3 px-4">المتسابق</th>
                <th className="py-3 px-4">النقاط والحسنات</th>
                <th className="py-3 px-4">آيات اليوم</th>
                <th className="py-3 px-4">التتابع</th>
                <th className="py-3 px-4">دقة التسميع</th>
                <th className="py-3 px-4">تشجيع أخوي</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-stone-100">
              {sortedFriends.map((friend) => {
                const isMe = friend.id === 'f_me';

                return (
                  <tr
                    key={friend.id}
                    className={`hover:bg-stone-50/80 transition-colors ${
                      isMe ? 'bg-emerald-50/40 font-semibold' : ''
                    }`}
                  >
                    <td className="py-3.5 px-4 font-bold text-stone-700">#{friend.rank}</td>

                    <td className="py-3.5 px-4">
                      <div className="flex items-center gap-2.5">
                        <span className="text-xl">{friend.avatar}</span>
                        <div>
                          <div className="font-bold text-stone-900">{friend.name}</div>
                          <span className="text-[11px] text-stone-500 font-normal">
                            {friend.lastActive}
                          </span>
                        </div>
                      </div>
                    </td>

                    <td className="py-3.5 px-4 font-bold text-emerald-800 text-sm">
                      {friend.points.toLocaleString('ar-EG')}
                    </td>

                    <td className="py-3.5 px-4 text-stone-700">{friend.versesToday} آية</td>

                    <td className="py-3.5 px-4">
                      <span className="inline-flex items-center gap-1 font-semibold text-amber-600">
                        <Flame className="w-3.5 h-3.5 fill-amber-500" />
                        {friend.streakDays} أيام
                      </span>
                    </td>

                    <td className="py-3.5 px-4 font-semibold text-emerald-700">
                      {friend.accuracy}%
                    </td>

                    <td className="py-3.5 px-4">
                      {isMe ? (
                        <span className="text-[11px] text-stone-400">حسابك الحالي</span>
                      ) : sentCheers[friend.id] ? (
                        <span className="text-[11px] text-emerald-700 font-bold bg-emerald-50 px-2 py-1 rounded-md animate-fade-in">
                          {sentCheers[friend.id]}
                        </span>
                      ) : (
                        <div className="flex items-center gap-1">
                          <button
                            onClick={() => handleSendCheer(friend.id, 'بارك الله في همتك! 🌟')}
                            className="bg-stone-100 hover:bg-stone-200 text-stone-700 px-2.5 py-1 rounded-lg text-[11px] transition-colors"
                          >
                            تشجيع 👏
                          </button>
                          <button
                            onClick={() => handleSendCheer(friend.id, 'تنافس على الخير! 🌿')}
                            className="bg-emerald-50 hover:bg-emerald-100 text-emerald-800 px-2 py-1 rounded-lg text-[11px] transition-colors"
                          >
                            دعاء 🤲
                          </button>
                        </div>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal: Add Friend */}
      {showAddFriend && (
        <div className="fixed inset-0 z-50 bg-black/50 backdrop-blur-xs flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl max-w-sm w-full p-6 space-y-4 shadow-xl">
            <h3 className="font-bold text-stone-900 text-base">إضافة رفيق إلى حلقة التنافس</h3>
            <p className="text-xs text-stone-500">
              أدخل اسم الصديق أو رمز المشاركة الخاص به للتنافس معاً.
            </p>

            <form onSubmit={handleAddFriend} className="space-y-3 text-xs">
              <input
                type="text"
                required
                placeholder="اسم الصديق (مثال: عبدالله الراجحي)"
                value={friendNameInput}
                onChange={(e) => setFriendNameInput(e.target.value)}
                className="w-full bg-stone-50 border border-stone-300 rounded-xl p-3 text-stone-900 text-xs focus:ring-2 focus:ring-emerald-600 focus:outline-none"
              />

              <div className="flex justify-end gap-2 pt-2">
                <button
                  type="button"
                  onClick={() => setShowAddFriend(false)}
                  className="px-3 py-1.5 text-stone-600 hover:bg-stone-100 rounded-lg font-semibold"
                >
                  إلغاء
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-emerald-700 hover:bg-emerald-800 text-white rounded-xl font-bold cursor-pointer"
                >
                  إضافة ومنافسة
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

